pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, address sender) public {
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));
        vm.assume(sender != address(c));
        vm.assume(amount > 0);
        vm.assume(amount <= 1000 ether);

        vm.deal(sender, amount);

        vm.warp(block.timestamp + 1);
        vm.roll(block.number + 1);

        uint256 prevBlockTime = c.pastBlockTime();
        uint256 prevBalance = address(c).balance;

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: amount}("");

        if (amount != 10 ether) {
            assertTrue(!ok, "call with invalid amount should revert");
        } else {
            assertTrue(ok, "call with exact 10 ether should succeed");
        }
    }
}
